				}
				else if (GlobalScript.inst.gameState.party_ideology[k] > 0 && GlobalScript.inst.gameState.is_party_enabled[k])
				{
					GlobalScript.inst.gameState.party_number[k] = GlobalScript.inst.gameState.party_ideology[k] + array[k];
